package com.smarthub.plus;
import android.content.Context;import android.security.keystore.*;import android.util.AtomicFile;import java.io.*;import java.net.URI;import java.nio.charset.StandardCharsets;import java.security.*;import javax.crypto.*;import javax.crypto.spec.GCMParameterSpec;import org.json.*;
/** Channel-scoped settings sealed with a non-exportable Android Keystore key. URLs never enter diagnostics. */
final class IPAudioBinding {
 final String url;final int delay,volume;final boolean enabled;
 IPAudioBinding(String url,int delay,int volume,boolean enabled)throws Exception{URI uri=new URI(url);if(!("https".equalsIgnoreCase(uri.getScheme())||"http".equalsIgnoreCase(uri.getScheme()))||uri.getHost()==null||url.length()>4096||delay<0||delay>30000||volume<0||volume>100)throw new IOException("INVALID_AUDIO_SETTINGS");this.url=url;this.delay=delay;this.volume=volume;this.enabled=enabled;}
 private static SecretKey key()throws Exception{KeyStore store=KeyStore.getInstance("AndroidKeyStore");store.load(null);String alias="iraqhub_ip_audio_v1";if(!store.containsAlias(alias)){KeyGenerator g=KeyGenerator.getInstance("AES","AndroidKeyStore");g.init(new KeyGenParameterSpec.Builder(alias,KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());g.generateKey();}return (SecretKey)store.getKey(alias,null);}
 private static File file(Context c,String physical)throws Exception{StringBuilder name=new StringBuilder();for(byte b:MessageDigest.getInstance("SHA-256").digest(physical.getBytes(StandardCharsets.UTF_8)))name.append(String.format(java.util.Locale.ROOT,"%02x",b&255));File dir=new File(c.getFilesDir(),"ip-audio");if(!dir.isDirectory()&&!dir.mkdirs())throw new IOException("AUDIO_STORE_UNAVAILABLE");return new File(dir,name+".sealed");}
 static synchronized IPAudioBinding read(Context c,String channel){try{AtomicFile file=new AtomicFile(file(c,channel));byte[] bytes=file.readFully();if(bytes.length<30||bytes.length>12000||bytes[0]!=1)return null;Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,java.util.Arrays.copyOfRange(bytes,1,13)));cipher.updateAAD(channel.getBytes(StandardCharsets.UTF_8));byte[] plain=cipher.doFinal(bytes,13,bytes.length-13);try{JSONObject j=new JSONObject(new String(plain,StandardCharsets.UTF_8));return new IPAudioBinding(j.getString("url"),j.getInt("delay"),j.getInt("volume"),j.getBoolean("enabled"));}finally{java.util.Arrays.fill(plain,(byte)0);}}catch(Exception absent){return null;}}
 synchronized void save(Context c,String channel)throws Exception{Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,key());cipher.updateAAD(channel.getBytes(StandardCharsets.UTF_8));byte[] plain=new JSONObject().put("url",url).put("delay",delay).put("volume",volume).put("enabled",enabled).toString().getBytes(StandardCharsets.UTF_8);byte[] encrypted;try{encrypted=cipher.doFinal(plain);}finally{java.util.Arrays.fill(plain,(byte)0);}AtomicFile file=new AtomicFile(file(c,channel));FileOutputStream out=file.startWrite();try{out.write(1);out.write(cipher.getIV());out.write(encrypted);file.finishWrite(out);}catch(Exception e){file.failWrite(out);throw e;}}
 static synchronized void remove(Context c,String channel)throws Exception{new AtomicFile(file(c,channel)).delete();}
}
